<script setup lang="ts">
import type { Listing } from '~/types/api'
import { useApi } from '~/composables/useApi'
import { money, listingStatus, dateTR } from '~/utils/format'
const api=useApi();const rows=ref<Listing[]>([]);const selected=ref<number[]>([]);const loading=ref(true);const error=ref('')
async function load(){loading.value=true;error.value='';try{rows.value=await api.listings({limit:100,offset:0,status:'active',sort_by:'updated_at',sort_order:'desc'});selected.value=selected.value.filter(id=>rows.value.some(r=>r.id===id))}catch(e){error.value=e instanceof Error?e.message:'İlanlar yüklenemedi.'}finally{loading.value=false}}
function toggle(id:number){if(selected.value.includes(id))selected.value=selected.value.filter(x=>x!==id);else if(selected.value.length<4)selected.value.push(id)}
const chosen=computed(()=>rows.value.filter(r=>selected.value.includes(r.id)))
await load()
</script>
<template><div class="page-heading"><div><p class="eyebrow">ANALİZ / KARŞILAŞTIRMA</p><h1>İlan karşılaştırma</h1><p>En fazla dört aktif ilan seçip fiyat, durum, kaynak ve kayıt tarihlerini yan yana değerlendirin.</p></div><button class="button button-secondary" @click="load">↻ Yenile</button></div>
<div v-if="error" class="alert">{{ error }}</div><section class="panel"><div class="panel-header"><div><h2>Karşılaştırılacak ilanları seçin</h2><p>Seçilen: {{ selected.length }}/4</p></div><button class="button button-secondary" @click="selected=[]">Seçimi temizle</button></div><StatePanel v-if="loading" state="loading"/><div v-else-if="!rows.length" class="empty-state">Aktif ilan bulunamadı.</div><div v-else class="listing-pick-grid"><label v-for="r in rows" :key="r.id" class="listing-pick"><input type="checkbox" :checked="selected.includes(r.id)" :disabled="!selected.includes(r.id)&&selected.length>=4" @change="toggle(r.id)"><span><b>İlan #{{ r.id }}</b><small>{{ money(r.asking_price,r.currency) }}</small><small>{{ listingStatus(r.status) }} · {{ dateTR(r.updated_at) }}</small></span></label></div></section>
<section v-if="chosen.length" class="panel"><h2>Karşılaştırma tablosu</h2><div class="table-wrap"><table><thead><tr><th>Özellik</th><th v-for="r in chosen" :key="r.id">İlan #{{ r.id }}</th></tr></thead><tbody><tr><th>İstenen fiyat</th><td v-for="r in chosen" :key="r.id">{{ money(r.asking_price,r.currency) }}</td></tr><tr><th>Gayrimenkul kaydı</th><td v-for="r in chosen" :key="r.id">#{{ r.property_id }}</td></tr><tr><th>Durum</th><td v-for="r in chosen" :key="r.id">{{ listingStatus(r.status) }}</td></tr><tr><th>Kaynak</th><td v-for="r in chosen" :key="r.id">{{ r.source_name || 'Belirtilmedi' }}</td></tr><tr><th>Son güncelleme</th><td v-for="r in chosen" :key="r.id">{{ dateTR(r.updated_at) }}</td></tr><tr><th>İşlem</th><td v-for="r in chosen" :key="r.id"><NuxtLink class="text-link" :to="`/listings/${r.id}`">Detayları aç</NuxtLink></td></tr></tbody></table></div><p class="muted-note">Bu sürümde karşılaştırma ilan API'sinde bulunan alanlarla sınırlıdır. Metrekare, otopark ve bina özellikleri için detay API'sinin genişletilmesi gerekir.</p></section></template>
<style scoped>.listing-pick-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}.listing-pick{display:flex;align-items:flex-start;gap:12px;padding:14px;border:1px solid var(--border,#dbe2ee);border-radius:10px;cursor:pointer}.listing-pick span{display:grid;gap:5px}.listing-pick small,.muted-note{color:var(--muted,#65738b);font-size:13px}.empty-state{padding:24px;color:var(--muted,#65738b)}</style>
